/* First screen adapted from the user-supplied HTML reference. */
let firstScreenCleanup=null;
function firstScreenHome(u){const ready=!!u?.character,progress=typeof kidProgress==='function'?kidProgress(u):{xp:0},route=ready?(u.tutorialDone?'map':'tutorial'):u?'character':'login',action=ready?'Продолжить путешествие':'Создать персонажа',completed=!!u?.story?.completed,badges=u?.rewards?.includes('kurai')?1:0;let time='dawn';try{time=localStorage.getItem('ethnohod-first-light')||time}catch{}if(!['dawn','day','dusk'].includes(time))time='dawn';return `<section class="first-screen" id="firstScreen" data-time="${time}"><div class="fs-sky"></div><svg class="fs-scene" viewBox="0 0 1600 900" preserveAspectRatio="xMidYMax slice" aria-hidden="true">
 <defs><radialGradient id="fs-glow"><stop offset="0" stop-color="#fff" stop-opacity=".9"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></radialGradient>
 <linearGradient id="fs-river" x1="0" x2="1"><stop offset="0" stop-color="#fff" stop-opacity="0"/><stop offset=".5" stop-color="#fff" stop-opacity=".6"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></linearGradient></defs>
 <g data-d="6"><circle cx="1130" cy="320" r="260" fill="url(#fs-glow)" opacity=".55" style="fill:url(#fs-glow)"/><circle cx="1130" cy="320" r="86" fill="var(--sun)"/></g>
 <g data-d="10" fill="#fff" opacity=".35"><g class="cl"><ellipse cx="300" cy="200" rx="150" ry="24"/><ellipse cx="400" cy="184" rx="90" ry="20"/></g><g class="cl" style="animation-duration:55s"><ellipse cx="900" cy="140" rx="170" ry="22"/></g></g>
 <g data-d="14"><path d="M-60 560L180 400 330 490 520 350 720 480 900 380 1100 490 1300 390 1660 540V900H-60Z" fill="var(--m1)"/></g>
 <g data-d="24"><path d="M-60 640Q200 540 380 600L560 480 620 510 700 440 830 540Q1000 580 1200 520Q1400 460 1660 560V900H-60Z" fill="var(--m2)"/><path d="M560 480L620 510 700 440 740 480 690 560 600 540Z" fill="#fff" opacity=".18"/></g>
 <g data-d="38"><path d="M-60 700Q300 610 600 660T1200 650 1660 670V900H-60Z" fill="var(--m3)"/><g data-fs-pines fill="var(--pine)"></g>
  <g transform="translate(1180 636)"><path d="M-70 0Q-70-62 0-62T70 0Z" fill="#f4ead0"/><rect x="-70" y="-14" width="140" height="14" fill="#e7d9b4"/><path d="M-70-14H70" stroke="#c4472f" stroke-width="4" stroke-dasharray="6 6"/><path d="M-14 0V-28Q0-38 14-28V0Z" fill="#5a3a22"/><path d="M0-62V-80" stroke="#ffc94a" stroke-width="3"/></g></g>
 <g data-d="52"><path d="M780 900Q960 800 880 740Q820 690 960 668L1020 672Q920 708 950 756Q1010 810 1060 900Z" fill="var(--riv)"/><path d="M830 900Q950 810 890 750 940 730 1000 700" stroke="url(#fs-river)" stroke-width="5" fill="none" class="sh"/></g>
</svg>
<div class="fs-title-wrap"><h1 class="fs-title" aria-label="Этноход">${'ЭТНОХОД'.split('').map((c,i)=>`<span aria-hidden="true" style="--letter:${i}">${c}</span>`).join('')}</h1></div>
<svg class="fs-scene" style="z-index:3;pointer-events:none" viewBox="0 0 1600 900" preserveAspectRatio="xMidYMax slice" aria-hidden="true">
 <g data-d="78"><path d="M-80 840Q300 740 760 800T1680 780V920H-80Z" fill="var(--near)"/><g data-fs-flowers></g></g>
 <g data-d="110" data-fs-birches></g>
</svg>
<div class="fs-ui"><div class="fs-top"><a class="fs-logo" href="#home" aria-label="Этноход — главная"><svg width="34" height="34" viewBox="0 0 40 40" fill="none" stroke="#ffc94a" stroke-width="1.8" aria-hidden="true"><circle cx="20" cy="20" r="4" fill="#ffc94a"/><ellipse cx="20" cy="9" rx="3.5" ry="7"/><ellipse cx="20" cy="31" rx="3.5" ry="7"/><ellipse cx="9" cy="20" rx="7" ry="3.5"/><ellipse cx="31" cy="20" rx="7" ry="3.5"/></svg>этноход</a><nav class="fs-nav" aria-label="Навигация первого экрана"><a href="#${u?'map':'login'}">Карта</a><a href="#${u?'book':'login'}">Книга открытий</a><a href="#teacher">Учителю</a></nav><div class="fs-hud">${u?`<a href="#profile" aria-label="Открыть профиль ${esc(u.nick)}">${esc(u.nick)}</a><span>${progress.xp} опыта</span>`:'<a href="#login/return">Уже играю →</a>'}</div></div>
<div class="fs-times" role="group" aria-label="Время суток">${[['dawn','Рассвет','🌅'],['day','День','☀️'],['dusk','Закат','🌇']].map(([id,name,icon])=>`<button type="button" data-fs-time="${id}" class="${time===id?'on':''}" aria-pressed="${time===id}" aria-label="${name}" title="${name}">${icon}</button>`).join('')}</div>
<div class="fs-copy"><h2>${ready?'Новые открытия уже ждут тебя!':'Большое путешествие начинается с тебя!'}</h2><p>${ready?'Выбирай, к кому отправиться в гости. Готовь угощения, узнавай новые слова и собирай подарки для своего героя.':'Создай путешественника и отправляйся в гости к народам России. Данияр уже ждёт в Башкортостане — поможем его семье подготовиться к празднику!'}</p><div class="fs-copy-actions"><a class="fs-primary-link" href="#${route}">${action} <span aria-hidden="true">↗</span></a>${!u?'<a class="fs-return-link" href="#login/return">У меня есть персонаж →</a>':'<a class="fs-return-link" href="#wardrobe">Мой рюкзак →</a>'}</div><div class="fs-chips"><span>${kidIcon('compass')} ${completed?'Первая глава пройдена':'Башкортостан открыт'}</span><span>${kidIcon('star')} ${u?badges+' значков':'Подарки за приключение'}</span><a href="#${u?'book':'login'}">${kidIcon('book')} Моя книга</a></div></div>
<a class="fs-cta" href="#${ready?'map':'about'}" aria-label="${ready?'Карта открытий':'Об игре'}"><svg viewBox="0 0 200 200" aria-hidden="true"><defs><path id="fs-cta-circle" d="M100 100m-82 0a82 82 0 1 1 164 0a82 82 0 1 1-164 0"/></defs><text><textPath href="#fs-cta-circle">${ready?'КАРТА ОТКРЫТИЙ · КАРТА ОТКРЫТИЙ':'ОБ ИГРЕ · ОТКРОЙ ЭТНОХОД · ОБ ИГРЕ'} · </textPath></text></svg><i><svg width="34" height="34" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" aria-hidden="true"><path d="M7 17L17 7M9 7h8v8"/></svg></i></a></div><div class="fs-grain"></div><div class="fs-fireflies" aria-hidden="true">${Array.from({length:20},(_,i)=>`<i style="--x:${(i*43+7)%100}%;--y:${45+(i*17)%50}%;--delay:${i*-.7}s"></i>`).join('')}</div></section>`}
function wireFirstScreen(){const root=document.querySelector('#firstScreen');if(!root)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)'),fine=matchMedia('(pointer: fine)');let seed=7823;const random=(a,b)=>{seed=(seed*16807)%2147483647;return a+(b-a)*seed/2147483647};let pines='';for(let i=0;i<70;i++){const x=random(-40,1640),y=700-Math.abs(Math.sin(x/300))*30+random(-10,30),s=random(.7,1.5);pines+=`<path d="M${x} ${y}l${-14*s} ${40*s}h${28*s}zM${x} ${y-22*s}l${-11*s} ${32*s}h${22*s}z"/>`}root.querySelector('[data-fs-pines]').innerHTML=pines;let flowers='';for(let i=0;i<80;i++){const x=random(-40,1640),y=random(800,890);flowers+=`<g class="fs-sway" style="animation-delay:${random(-6,0)}s"><path d="M${x} ${y}v-${random(14,32)}" stroke="#2f6a38" stroke-width="2"/><circle cx="${x}" cy="${y-random(18,34)}" r="${random(3,6)}" fill="${['#9b6fd0','#c28bf0','#ffd966','#fff'][i%4]}"/></g>`}root.querySelector('[data-fs-flowers]').innerHTML=flowers;const birch=(x,h,w)=>{let tree=`<g class="fs-sway" style="animation-delay:${random(-6,0)}s"><path d="M${x} 920L${x+w*.2} ${900-h}" stroke="#efe8d8" stroke-width="${w}" stroke-linecap="round"/>`;for(let k=0;k<9;k++){const y=random(920-h,900);tree+=`<path d="M${x-w/2} ${y}h${w*.45}" stroke="#2a2a2a" stroke-width="3"/>`}for(let n=0;n<14;n++)tree+=`<ellipse cx="${x+random(-90,90)+w}" cy="${900-h+random(-30,120)}" rx="${random(26,46)}" ry="${random(14,26)}" fill="var(--leaf)" opacity="${random(.75,1)}"/>`;return tree+'</g>'};root.querySelector('[data-fs-birches]').innerHTML=[[-10,900,26],[90,720,18],[220,560,12],[1470,880,24],[1560,760,20],[1380,560,12]].map(v=>birch(...v)).join('');root.querySelectorAll('[data-fs-time]').forEach(b=>b.onclick=()=>{root.dataset.time=b.dataset.fsTime;root.querySelectorAll('[data-fs-time]').forEach(v=>{v.classList.toggle('on',v===b);v.setAttribute('aria-pressed',String(v===b))});try{localStorage.setItem('ethnohod-first-light',b.dataset.fsTime)}catch{}});let frame=0,mx=0,my=0,cx=0,cy=0,active=false;const layers=Array.from(root.querySelectorAll('[data-d]'));const move=e=>{if(reduced.matches||!fine.matches)return;mx=e.clientX/innerWidth-.5;my=e.clientY/innerHeight-.5;active=true;if(!frame)frame=requestAnimationFrame(tick)};const tick=()=>{frame=0;if(!root.isConnected||reduced.matches||document.hidden)return;cx+=(mx-cx)*.08;cy+=(my-cy)*.08;layers.forEach(g=>{const depth=+g.dataset.d;g.style.transform=`translate(${-cx*depth*.8}px,${-cy*depth*.3}px)`});if(Math.abs(mx-cx)+Math.abs(my-cy)>.001)frame=requestAnimationFrame(tick)};const leave=()=>{mx=0;my=0;if(!frame&&!reduced.matches)frame=requestAnimationFrame(tick)};root.addEventListener('pointermove',move);root.addEventListener('pointerleave',leave);firstScreenCleanup=()=>{cancelAnimationFrame(frame);root.removeEventListener('pointermove',move);root.removeEventListener('pointerleave',leave);firstScreenCleanup=null}}
